using System;using System.Linq;using System.Drawing;using System.Collections.Generic;using System.Threading.Tasks;
namespace BeamScheduleFormatter {
partial class WindSiteMap {
 public bool ShowContours=true;string contourCategory="III-V";List<WindContourSegment> contourLines;
 public void SetWindCategory(string category){if(contourLines!=null&&contourCategory==category)return;contourCategory=category;contourLines=WindTin.Contours(category);Invalidate();}
 public void ViewWindRegion(){if(!double.IsNaN(siteLat)){latitude=siteLat;longitude=siteLon;}zoom=8;Queue();}
 void DrawWindOverlay(Graphics g){if(ShowContours&&contourLines!=null){var labels=new HashSet<double>();foreach(var line in contourLines){var a=Pixel(line.Lat1,line.Lon1);var b=Pixel(line.Lat2,line.Lon2);if(Math.Max(a.X,b.X)<0||Math.Min(a.X,b.X)>Width||Math.Max(a.Y,b.Y)<0||Math.Min(a.Y,b.Y)>Height)continue;using(var pen=new Pen(Color.FromArgb(175,134,57,89),1.4f))g.DrawLine(pen,a,b);if(labels.Add(line.Speed)&&a.X>50&&a.X<Width-100&&a.Y>40&&a.Y<Height-50)System.Windows.Forms.TextRenderer.DrawText(g,line.Speed.ToString("0")+" km/h",ModernUi.Strong,Point.Round(a),Color.FromArgb(110,35,67),Color.White);}}
  if(terrain==null)return;var center=Pixel(terrain.Lat,terrain.Lon);
  var boundaryPoints=Enumerable.Range(0,145).Select(i=>{var point=WindAssessment.Destination(terrain.Lat,terrain.Lon,i*2.5,terrain.Radius);return Pixel(point[0],point[1]);}).ToArray();
  if(ShowRoughness&&roughness!=null&&terrain.CoverGrid!=null){var state=g.Save();using(var clip=new System.Drawing.Drawing2D.GraphicsPath()){clip.AddPolygon(boundaryPoints);g.SetClip(clip,System.Drawing.Drawing2D.CombineMode.Intersect);var grid=terrain.CoverGrid;var a=Pixel(grid.North,grid.West);var b=Pixel(grid.South,grid.East);g.DrawImage(roughness,new RectangleF(a.X,a.Y,b.X-a.X,b.Y-a.Y));}g.Restore(state);}
  for(int i=0;i<8;i++){var audit=WindAssessment.AssessExposure(terrain,i,referenceHeight);var geo=WindCircleGeometry.Sector(terrain.Lat,terrain.Lon,terrain.Radius,i);var polygon=geo.Select(point=>Pixel(point[0],point[1])).ToArray();if(ShowRoughness&&roughness==null)using(var brush=new SolidBrush(Color.FromArgb(46,WindColors.Roughness(audit.Roughness))))g.FillPolygon(brush,polygon);if(ShowDirections){using(var pen=new Pen(Color.FromArgb(130,65,76,88),1))g.DrawLine(pen,center,polygon[1]);var endpoint=WindAssessment.Destination(terrain.Lat,terrain.Lon,i*45,terrain.Radius);var point=Pixel(endpoint[0],endpoint[1]);System.Windows.Forms.TextRenderer.DrawText(g,WindAssessment.Directions[i]+" / Exposure "+audit.Exposure,ModernUi.Body,new Rectangle((int)point.X-70,(int)point.Y-15,140,36),Color.FromArgb(32,43,53),Color.White,System.Windows.Forms.TextFormatFlags.HorizontalCenter|System.Windows.Forms.TextFormatFlags.WordBreak);}}
  var ring=Enumerable.Range(0,145).Select(i=>{var p=WindAssessment.Destination(terrain.Lat,terrain.Lon,i*2.5,terrain.Radius);return Pixel(p[0],p[1]);}).ToArray();using(var pen=new Pen(Color.FromArgb(180,52,68,83),1.4f))g.DrawLines(pen,ring);
  if(WindTin.Finite(referenceHeight)&&referenceHeight>0){foreach(double radius in new[]{WindAssessment.BFetch(referenceHeight),WindAssessment.DFetch(referenceHeight)+WindAssessment.DTransition(referenceHeight)}.Distinct()){if(radius>terrain.Radius)continue;var points=Enumerable.Range(0,73).Select(i=>{var p=WindAssessment.Destination(terrain.Lat,terrain.Lon,i*5,radius);return Pixel(p[0],p[1]);}).ToArray();using(var pen=new Pen(Color.FromArgb(145,65,74,86),1){DashStyle=System.Drawing.Drawing2D.DashStyle.Dash})g.DrawLines(pen,points);}System.Windows.Forms.TextRenderer.DrawText(g,"h = "+referenceHeight.ToString("0.##")+" m  |  assessment radius "+terrain.Radius.ToString("0")+" m  |  B fetch "+WindAssessment.BFetch(referenceHeight).ToString("0")+" m  |  D fetch + transition "+(WindAssessment.DFetch(referenceHeight)+WindAssessment.DTransition(referenceHeight)).ToString("0")+" m",ModernUi.Body,new Rectangle(55,6,Math.Max(150,Width-65),35),Color.FromArgb(32,43,53),Color.White);}else System.Windows.Forms.TextRenderer.DrawText(g,"Enter building geometry to determine mean roof height h and assess exposure.",ModernUi.Body,new Rectangle(55,6,Math.Max(150,Width-65),35),Color.FromArgb(32,43,53),Color.White);
 }
}
}
